INSERT INTO products (name, brand, description, price, image, category, featured, in_stock, rating, reviews, fragrance, size) VALUES
('Rose Mystique', 'Scent Trail', 'A romantic floral masterpiece weaving together Bulgarian rose and peony with hints of raspberry. The heart blooms with iris and magnolia, resting on a luxurious base of cashmere musk and white cedar.', 950, '/perfume1.jpg', 'floral', false, true, 4.6, 68, '{"topNotes":["Bulgarian Rose","Raspberry"],"middleNotes":["Iris","Magnolia"],"baseNotes":["Cashmere Musk","White Cedar"]}', '{"value":50,"unit":"ml"}'),
('Amber Oud Royale', 'Scent Trail', 'An opulent oriental creation that commands attention. Rich saffron and pink pepper ignite the senses, while precious oud and amber form a majestic heart, lingering with deep benzoin and labdanum.', 2200, '/perfume2.jpg', 'oriental', true, true, 4.9, 142, '{"topNotes":["Saffron","Pink Pepper"],"middleNotes":["Oud","Amber"],"baseNotes":["Benzoin","Labdanum"]}', '{"value":50,"unit":"ml"}'),
('Bergamot & Yuzu', 'Scent Trail', 'A sparkling citrus composition that radiates pure freshness. Bright yuzu and bergamot dance with green tea accords, while white musk and blonde woods create a clean, uplifting dry-down.', 680, '/perfume3.jpg', 'citrus', false, true, 4.4, 55, '{"topNotes":["Yuzu","Bergamot"],"middleNotes":["Green Tea","Neroli"],"baseNotes":["White Musk","Blonde Woods"]}', '{"value":50,"unit":"ml"}'),
('Arctic Mist', 'Scent Trail', 'A crisp, invigorating fresh fragrance inspired by Nordic landscapes. Cool eucalyptus and frozen mint open the scent, leading to a heart of water lily and ozone, settling into driftwood and sea moss.', 780, '/perfume4.jpg', 'fresh', false, true, 4.5, 61, '{"topNotes":["Eucalyptus","Frozen Mint"],"middleNotes":["Water Lily","Ozone"],"baseNotes":["Driftwood","Sea Moss"]}', '{"value":50,"unit":"ml"}'),
('Smoky Sandalwood', 'Scent Trail', 'A deep, contemplative woody fragrance with smoky allure. Birch tar and black pepper create an intense opening, while creamy sandalwood and guaiac wood form the soul, finishing with leather and dark vanilla.', 1400, '/perfume5.jpg', 'woody', true, true, 4.8, 110, '{"topNotes":["Birch Tar","Black Pepper"],"middleNotes":["Sandalwood","Guaiac Wood"],"baseNotes":["Leather","Dark Vanilla"]}', '{"value":50,"unit":"ml"}'),
('Caramel Brûlée', 'Scent Trail', 'An irresistible gourmand treat that wraps you in warmth. Toasted coconut and brown sugar open sweetly, while salted caramel and coffee create an addictive heart, finished with warm musk and amber.', 990, '/perfume6.jpg', 'gourmand', false, true, 4.7, 79, '{"topNotes":["Toasted Coconut","Brown Sugar"],"middleNotes":["Salted Caramel","Coffee"],"baseNotes":["Warm Musk","Amber"]}', '{"value":50,"unit":"ml"}');